// Port of the parts of Go's unicode package used by Lute, plus the East Asian
// width check that replaces golang.org/x/text/width in render/space.go.
//
// All data lives in unicode_tables.ts, which is generated by
// ts/tools/gen-unicode from the real Go functions for every code point
// 0..0x10FFFF. Nothing here uses JS regex Unicode classes, toLowerCase,
// toUpperCase or Intl, because their Unicode versions and casing rules differ
// from Go's.
//
// Every predicate has an ASCII fast path that reads a 128-entry flags table
// instead of the range table. Values outside 0..0x10FFFF are handled the same
// way Go handles them (predicates return false, mappings return the input).

import {
  asciiFlags,
  asciiSimpleFold,
  EastAsianWideOrFullwidthRanges,
  GraphicRanges,
  ControlRanges,
  DigitRanges,
  LetterRanges,
  LowerMap,
  LowerRanges,
  MarkRanges,
  NumberRanges,
  PrintRanges,
  PunctRanges,
  SimpleFoldMap,
  SpaceRanges,
  SymbolRanges,
  TitleMap,
  UpperMap,
  UpperRanges,
} from "./unicode_tables.ts";

export {
  Han,
  Hiragana,
  Katakana,
  Hangul,
  Zs,
  Lm,
  Latin,
  L,
  M,
  N,
  P,
  S,
  Nd,
  Lu,
  Ll,
  White_Space,
} from "./unicode_tables.ts";

export const MaxASCII = 0x7f;
export const MaxLatin1 = 0xff;
export const MaxRune = 0x10ffff;
export const ReplacementChar = 0xfffd;
export const Version = "15.0.0";

// Bit positions in asciiFlags. They must match the order in unicode_tables.ts.
const BIT_LETTER = 1 << 0;
const BIT_DIGIT = 1 << 1;
const BIT_NUMBER = 1 << 2;
const BIT_PUNCT = 1 << 3;
const BIT_SYMBOL = 1 << 4;
const BIT_SPACE = 1 << 5;
const BIT_CONTROL = 1 << 6;
const BIT_PRINT = 1 << 7;
const BIT_GRAPHIC = 1 << 8;
const BIT_UPPER = 1 << 9;
const BIT_LOWER = 1 << 10;
const BIT_MARK = 1 << 11;
const BIT_EAW = 1 << 12;

// inRanges reports whether r lies in one of the inclusive [lo, hi] pairs.
function inRanges(ranges: Uint32Array, r: number): boolean {
  let lo = 0;
  let hi = (ranges.length >> 1) - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (r < ranges[2 * mid]) {
      hi = mid - 1;
    } else if (r > ranges[2 * mid + 1]) {
      lo = mid + 1;
    } else {
      return true;
    }
  }
  return false;
}

// lookupMap returns the mapped value for r in a flat [rune, mapped] table, or
// -1 when r is not in the table (the mapping is the identity).
function lookupMap(map: Uint32Array, r: number): number {
  let lo = 0;
  let hi = (map.length >> 1) - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const key = map[2 * mid];
    if (r < key) {
      hi = mid - 1;
    } else if (r > key) {
      lo = mid + 1;
    } else {
      return map[2 * mid + 1];
    }
  }
  return -1;
}

// classify answers a predicate for r using the ASCII flags bit or the range table.
function classify(bit: number, ranges: Uint32Array, r: number): boolean {
  if (r >= 0 && r <= MaxASCII) {
    return (asciiFlags[r] & bit) !== 0;
  }
  if (r < 0 || r > MaxRune) {
    return false;
  }
  return inRanges(ranges, r);
}

// Is reports whether the rune r is in the range table. A table is a flat
// Uint32Array of inclusive [lo, hi] pairs sorted by lo.
export function Is(table: Uint32Array, r: number): boolean {
  if (r < 0) {
    return false;
  }
  return inRanges(table, r);
}

export function IsLetter(r: number): boolean {
  return classify(BIT_LETTER, LetterRanges, r);
}

export function IsDigit(r: number): boolean {
  return classify(BIT_DIGIT, DigitRanges, r);
}

export function IsNumber(r: number): boolean {
  return classify(BIT_NUMBER, NumberRanges, r);
}

export function IsPunct(r: number): boolean {
  return classify(BIT_PUNCT, PunctRanges, r);
}

export function IsSymbol(r: number): boolean {
  return classify(BIT_SYMBOL, SymbolRanges, r);
}

export function IsSpace(r: number): boolean {
  return classify(BIT_SPACE, SpaceRanges, r);
}

export function IsControl(r: number): boolean {
  return classify(BIT_CONTROL, ControlRanges, r);
}

export function IsPrint(r: number): boolean {
  return classify(BIT_PRINT, PrintRanges, r);
}

export function IsGraphic(r: number): boolean {
  return classify(BIT_GRAPHIC, GraphicRanges, r);
}

export function IsUpper(r: number): boolean {
  return classify(BIT_UPPER, UpperRanges, r);
}

export function IsLower(r: number): boolean {
  return classify(BIT_LOWER, LowerRanges, r);
}

export function IsMark(r: number): boolean {
  return classify(BIT_MARK, MarkRanges, r);
}

// IsEastAsianWideOrFullwidth reports whether width.LookupRune(r).Kind() is
// width.EastAsianWide or width.EastAsianFullwidth in golang.org/x/text v0.21.0.
export function IsEastAsianWideOrFullwidth(r: number): boolean {
  return classify(BIT_EAW, EastAsianWideOrFullwidthRanges, r);
}

// ToUpper maps r to upper case (unicode.ToUpper).
export function ToUpper(r: number): number {
  if (r <= MaxASCII) {
    return r >= 0x61 && r <= 0x7a ? r - 0x20 : r;
  }
  if (r > MaxRune) {
    return r;
  }
  const m = lookupMap(UpperMap, r);
  return m < 0 ? r : m;
}

// ToLower maps r to lower case (unicode.ToLower).
export function ToLower(r: number): number {
  if (r <= MaxASCII) {
    return r >= 0x41 && r <= 0x5a ? r + 0x20 : r;
  }
  if (r > MaxRune) {
    return r;
  }
  const m = lookupMap(LowerMap, r);
  return m < 0 ? r : m;
}

// ToTitle maps r to title case (unicode.ToTitle).
export function ToTitle(r: number): number {
  if (r <= MaxASCII) {
    return r >= 0x61 && r <= 0x7a ? r - 0x20 : r;
  }
  if (r > MaxRune) {
    return r;
  }
  const m = lookupMap(TitleMap, r);
  return m < 0 ? r : m;
}

// SimpleFold iterates over Unicode code points equivalent under simple case
// folding (unicode.SimpleFold). Runes outside 0..0x10FFFF are returned unchanged.
export function SimpleFold(r: number): number {
  if (r < 0 || r > MaxRune) {
    return r;
  }
  if (r <= MaxASCII) {
    return asciiSimpleFold[r];
  }
  const m = lookupMap(SimpleFoldMap, r);
  return m < 0 ? r : m;
}
